package bench

import (
	"math/big"
	"testing"

	"github.com/blackchip-org/zc/v6/app"
	"github.com/blackchip-org/zc/v6/app/ops"
	"github.com/blackchip-org/zc/v6/app/types"
	"github.com/blackchip-org/zc/v6/pkg/calc"
)

const fact1000 = ""

func factorialZcTest(n int) *big.Int {
	c := app.NewCalc()
	c.PushVal(1)
	for i := 1; i <= n; i++ {
		c.PushVal(i)
		c.Do(ops.BigIntMul)
	}
	return types.BigInt.As(c.Pop())
}

func factorialCalcTest(n int) *big.Int {
	c := calc.NewBigInt()
	c.PushInt(1)
	for i := 1; i <= n; i++ {
		c.PushInt(i)
		c.Mul()
	}
	return c.Pop()
}

func factorialTestNative(n int) *big.Int {
	var x, y big.Int
	x.SetInt64(int64(1))
	for i := 1; i <= n; i++ {
		y.SetInt64(int64(i))
		x.Mul(&x, &y)
	}
	return &x
}

func TestFactorialZc(t *testing.T) {
	result := factorialZcTest(1000).String()
	if result != fact1000 {
		t.Fatalf("\n have: %v \n want: %v", result, fact1000)
	}
}

func TestFactorialCalc(t *testing.T) {
	result := factorialCalcTest(1000).String()
	if result != fact1000 {
		t.Fatalf("\n have: %v \n want: %v", result, fact1000)
	}
}

func TestFactorialNative(t *testing.T) {
	result := factorialTestNative(1000).String()
	if result != fact1000 {
		t.Fatalf("\n have: %v \n want: %v", result, fact1000)
	}
}

func BenchmarkFactorialZc(b *testing.B) {
	for i := 0; i < b.N; i++ {
		factorialZcTest(1000)
	}
}

func BenchmarkFactorialCalc(b *testing.B) {
	for i := 0; i < b.N; i++ {
		factorialCalcTest(1000)
	}
}

func BenchmarkFactorialNative(b *testing.B) {
	for i := 0; i < b.N; i++ {
		factorialTestNative(1000)
	}
}
